import hashlib

# WRONG: one fast, unsalted hash per password (the LinkedIn 2012 pattern)
def store_wrong(password: str) -> str:
    return hashlib.sha1(password.encode()).hexdigest()

users = {"ana": "123456", "ben": "sunshine", "cy": "123456"}
table = {name: store_wrong(pw) for name, pw in users.items()}
for name, h in table.items():
    print(name, h)
# ana and cy get the SAME hash: crack one, you have both
